#ifndef RUNNER_PUSH_OVERLAP_H
#define RUNNER_PUSH_OVERLAP_H

#include <stdbool.h>
#include <stdint.h>

#include "core/canvas.h"

#ifdef __cplusplus
extern "C" {
#endif

/* Lets a hack that repaints its whole canvas every step (HackEntry
 * repaints_all) draw its next frame while a worker pushes the last one. Two
 * pixel buffers swap roles each frame: present() hands the finished one to the
 * worker and points the canvas at the other. */
typedef struct PushOverlap PushOverlap;

/* The platform's thread primitives: FreeRTOS on the device, pthreads in the
 * host tests. sem_destroy may be NULL. */
typedef struct {
  void *(*sem_create)(void); /* binary semaphore, starts empty */
  void (*sem_give)(void *sem);
  void (*sem_take)(void *sem); /* blocks */
  int (*spawn)(void (*body)(void *), void *arg); /* 0 on success */
  uint32_t (*now_us)(void);
  void (*sem_destroy)(void *sem);
} PushOverlapOps;

/* Runs on the worker: pushes the dirty rows of view, a canvas whose px is the
 * finished frame. Returns the rows sent. */
typedef int (*PushOverlapPush)(void *ctx, Canvas *view);

/* spare is a buffer the size of canvas->px that the module may swap in; the
 * caller keeps ownership. Returns NULL if spare is NULL or anything fails to
 * allocate or start. */
PushOverlap *push_overlap_create(const Canvas *canvas, uint16_t *spare,
                                 const PushOverlapOps *ops, PushOverlapPush push,
                                 void *push_ctx);

/* Waits for the worker, then, if eligible and something is dirty, hands the
 * frame to the worker, swaps canvas->px with the spare and returns true.
 * Otherwise returns false and the caller pushes synchronously: if the canvas
 * was swapped, the newest frame is swapped back in first (and canvas's dirty
 * spans cleared, since the display already shows it). */
bool push_overlap_present(PushOverlap *p, Canvas *canvas, bool eligible);
/* Blocks until the worker is idle. */
void push_overlap_wait(PushOverlap *p);
/* Waits, then forgets the newest frame without swapping: call when a new hack
 * starts, whose canvas is the one to keep. */
void push_overlap_reset(PushOverlap *p);
/* How long the push that ran beside the last step took; 0 after a synchronous
 * present. A hack's delay is spent by this much. */
uint32_t push_overlap_credit_us(const PushOverlap *p);
/* Rows sent by pushes that finished since the last call. */
int push_overlap_take_rows(PushOverlap *p);
void push_overlap_destroy(PushOverlap *p);

#ifdef __cplusplus
}
#endif

#endif

#include "runner/push_overlap.h"

#include <stdlib.h>
#include <string.h>

struct PushOverlap {
  PushOverlapOps ops;
  PushOverlapPush push;
  void *ctx;
  Canvas view;
  uint16_t *spare;
  uint16_t *newest; /* the buffer that holds the latest pushed frame */
  void *go, *done;
  bool busy, quit;
  int rows_result, rows_taken;
  uint32_t dur_result, last_us, credit_us;
};

static void worker(void *arg) {
  PushOverlap *p = arg;
  for (;;) {
    p->ops.sem_take(p->go);
    if (p->quit) break;
    uint32_t t0 = p->ops.now_us();
    p->rows_result = p->push(p->ctx, &p->view);
    p->dur_result = p->ops.now_us() - t0;
    p->ops.sem_give(p->done);
  }
  p->ops.sem_give(p->done);
}

static void release(PushOverlap *p) {
  if (p->ops.sem_destroy) {
    if (p->go) p->ops.sem_destroy(p->go);
    if (p->done) p->ops.sem_destroy(p->done);
  }
  free(p->view.dirty_x0);
  free(p->view.dirty_x1);
  free(p);
}

PushOverlap *push_overlap_create(const Canvas *canvas, uint16_t *spare,
                                 const PushOverlapOps *ops, PushOverlapPush push,
                                 void *push_ctx) {
  if (!spare) return NULL;
  PushOverlap *p = calloc(1, sizeof *p);
  if (!p) return NULL;
  p->ops = *ops;
  p->push = push;
  p->ctx = push_ctx;
  p->spare = spare;
  p->view = *canvas;
  p->view.dirty_x0 = malloc((size_t)canvas->h * sizeof(int16_t));
  p->view.dirty_x1 = malloc((size_t)canvas->h * sizeof(int16_t));
  p->go = ops->sem_create();
  p->done = ops->sem_create();
  if (!p->view.dirty_x0 || !p->view.dirty_x1 || !p->go || !p->done ||
      ops->spawn(worker, p) != 0) {
    release(p);
    return NULL;
  }
  return p;
}

void push_overlap_wait(PushOverlap *p) {
  if (!p->busy) return;
  p->ops.sem_take(p->done);
  p->busy = false;
  p->rows_taken += p->rows_result;
  p->last_us = p->dur_result;
}

void push_overlap_reset(PushOverlap *p) {
  push_overlap_wait(p);
  p->newest = NULL;
}

static bool any_dirty(const Canvas *c) {
  int x0, x1;
  for (int y = 0; y < c->h; y++)
    if (canvas_dirty_row(c, y, &x0, &x1)) return true;
  return false;
}

bool push_overlap_present(PushOverlap *p, Canvas *canvas, bool eligible) {
  push_overlap_wait(p);
  if (eligible && any_dirty(canvas)) {
    memcpy(p->view.dirty_x0, canvas->dirty_x0,
           (size_t)canvas->h * sizeof(int16_t));
    memcpy(p->view.dirty_x1, canvas->dirty_x1,
           (size_t)canvas->h * sizeof(int16_t));
    canvas_clear_dirty(canvas);
    p->view.px = canvas->px;
    p->newest = canvas->px;
    canvas->px = p->spare;
    p->spare = p->newest;
    p->credit_us = p->last_us;
    p->busy = true;
    p->ops.sem_give(p->go);
    return true;
  }
  if (p->newest && p->newest != canvas->px) {
    p->spare = canvas->px;
    canvas->px = p->newest;
    canvas_clear_dirty(canvas);
  }
  p->newest = NULL;
  p->credit_us = 0;
  return false;
}

uint32_t push_overlap_credit_us(const PushOverlap *p) { return p->credit_us; }

int push_overlap_take_rows(PushOverlap *p) {
  int n = p->rows_taken;
  p->rows_taken = 0;
  return n;
}

void push_overlap_destroy(PushOverlap *p) {
  if (!p) return;
  push_overlap_wait(p);
  p->quit = true;
  p->ops.sem_give(p->go);
  p->ops.sem_take(p->done);
  release(p);
}

